import * as SciChart from "scichart";

// #region_A_start
// Create a JavaScript population density map with SciChart.js: every county in the contiguous United States,
// shown as a choropleth (one colour per county) or as a dot density map (one dot per 200, 1,000 or 5,000 people)
// (the 3D view, density as columns, is populationDensity3D() further down)
const {
    SciChartSurface,
    NumericAxis,
    NumberRange,
    XyDataSeries,
    FastTriangleRenderableSeries,
    ETriangleSeriesDrawMode,
    FastLineRenderableSeries,
    XyScatterRenderableSeries,
    SquarePointMarker,
    BoxAnnotation,
    NativeTextAnnotation,
    ECoordinateMode,
    EHorizontalAnchorPoint,
    EVerticalAnchorPoint,
    EMultiLineAlignment,
    Thickness,
    CustomChartModifier2D,
    translateFromCanvasToSeriesViewRect,
    MouseWheelZoomModifier,
    ZoomPanModifier,
    ZoomExtentsModifier,
    SciChartJsNavyTheme,
    SciChart3DSurface,
    NumericAxis3D,
    Vector3,
    XyzDataSeries3D,
    ColumnRenderableSeries3D,
    CubePointMarker3D,
    PointLineRenderableSeries3D,
    OrbitModifier3D,
    MouseWheelZoomModifier3D,
    ResetCamera3DModifier,
    TooltipModifier3D,
    parseColorToUIntArgb
} = SciChart;
// or, for npm, import { SciChartSurface, ... } from "scichart"

// Dot values to choose from. With fewer, bigger dots, each dot needs more ink to stay visible;
// with millions of small dots, see-through dots stop dense areas turning into one solid blob.
const DOT_STYLES = [
    { peoplePerDot: 200, fill: "#FFD16618", size: 1 },
    { peoplePerDot: 1000, fill: "#FFD16660", size: 1 },
    { peoplePerDot: 5000, fill: "#FFD166", size: 2 }
];

// Choropleth classes in people per square mile. County densities run from under 1 to over 70,000,
// so the breaks grow about five times from one class to the next. Brighter means denser on a dark background.
const DENSITY_CLASSES = [
    { label: "Under 10", max: 10, color: "#46327E" },
    { label: "10 to 50", max: 50, color: "#365C8D" },
    { label: "50 to 250", max: 250, color: "#1F9A8A" },
    { label: "250 to 1,000", max: 1000, color: "#6CCE59" },
    { label: "1,000 and over", max: Infinity, color: "#FDE725" }
];

function getClassIndex(density) {
    return DENSITY_CLASSES.findIndex((densityClass) => density < densityClass.max);
}

// 1. DATA HELPERS (plain JavaScript, no SciChart code)

// Decode one outline from the encoded polyline format (the same idea as Google's polyline encoding):
// each number is the change from the previous point in whole kilometres, written in 5-bit chunks as characters.
function decodeOutline(encoded) {
    const points = [];
    let index = 0;
    let x = 0;
    let y = 0;
    const nextNumber = () => {
        let result = 0;
        let shift = 0;
        let chunk;
        do {
            chunk = encoded.charCodeAt(index++) - 63;
            result |= (chunk & 0x1f) << shift;
            shift += 5;
        } while (chunk >= 0x20);
        return result & 1 ? ~(result >> 1) : result >> 1;
    };
    while (index < encoded.length) {
        x += nextNumber();
        y += nextNumber();
        points.push([x, y]);
    }
    return points;
}

// The triangle series draws triangles, not polygons, so each outline is cut into triangles by ear clipping:
// repeatedly cut off a corner ("ear") that has no other point inside it.
// For large or complex maps, use a tested library such as earcut, or triangulate once offline.
function triangulateRing(ring) {
    const points = ring.slice();
    let signedArea = 0;
    points.forEach(([x1, y1], i) => {
        const [x2, y2] = points[(i + 1) % points.length];
        signedArea += x1 * y2 - x2 * y1;
    });
    if (signedArea < 0) points.reverse(); // make the ring counter-clockwise

    const cross = (a, b, c) => (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    const isInside = (p, a, b, c) => cross(a, b, p) >= 0 && cross(b, c, p) >= 0 && cross(c, a, p) >= 0;

    const remaining = points;
    const triangles = []; // flat list: every three points make one triangle
    while (remaining.length > 3) {
        const n = remaining.length;
        let earIndex = -1;
        for (let i = 0; i < n && earIndex < 0; i++) {
            const a = remaining[(i + n - 1) % n];
            const b = remaining[i];
            const c = remaining[(i + 1) % n];
            if (cross(a, b, c) <= 0) continue; // not a convex corner
            const blocked = remaining.some(
                (p) => p !== a && p !== b && p !== c && !(p[0] === b[0] && p[1] === b[1]) && isInside(p, a, b, c)
            );
            if (!blocked) {
                triangles.push(a, b, c);
                earIndex = i;
            }
        }
        if (earIndex < 0) {
            // No ear found: drop a point that lies on a straight line, or stop
            earIndex = remaining.findIndex((b, i) => cross(remaining[(i + n - 1) % n], b, remaining[(i + 1) % n]) === 0);
            if (earIndex < 0) break;
        }
        remaining.splice(earIndex, 1);
    }
    if (remaining.length === 3) triangles.push(...remaining);
    return triangles;
}

// Is the point inside the ring? (ray casting: count how many edges a horizontal line from the point crosses)
function isPointInRing(x, y, ring) {
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const [xi, yi] = ring[i];
        const [xj, yj] = ring[j];
        if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
}

// Flatten rings into x and y arrays with NaN between rings, so one line series draws them all with gaps
function ringsToLine(rings, closeRings) {
    const xValues = [];
    const yValues = [];
    rings.forEach((ring) => {
        ring.forEach(([x, y]) => {
            xValues.push(x);
            yValues.push(y);
        });
        if (closeRings) {
            xValues.push(ring[0][0]);
            yValues.push(ring[0][1]);
        }
        xValues.push(NaN);
        yValues.push(NaN);
    });
    return { xValues, yValues };
}

// A seeded random number generator, so the dots land in the same places every time
function createRandom(seed) {
    return () => {
        seed = (seed * 16807) % 2147483647;
        return (seed - 1) / 2147483646;
    };
}

// 2. DOT DENSITY: county.dotCount dots per county, each at a random place inside the county.
// A triangle is picked with a chance in proportion to its area, then a random point inside it,
// so the dots are spread evenly over the county.
function placeDots(counties, random) {
    const total = counties.reduce((sum, county) => sum + county.dotCount, 0);
    const xValues = new Float64Array(total);
    const yValues = new Float64Array(total);
    let next = 0;
    counties.forEach((county) => {
        const { triangles, cumulativeAreas } = county;
        const totalArea = cumulativeAreas[cumulativeAreas.length - 1];
        for (let d = 0; d < county.dotCount; d++) {
            // Binary search for the triangle that holds this share of the area
            const target = random() * totalArea;
            let low = 0;
            let high = cumulativeAreas.length - 1;
            while (low < high) {
                const mid = (low + high) >> 1;
                if (cumulativeAreas[mid] < target) low = mid + 1;
                else high = mid;
            }
            const [a, b, c] = [triangles[low * 3], triangles[low * 3 + 1], triangles[low * 3 + 2]];
            // A uniform random point in the triangle: fold points from the far half back in
            let u = random();
            let v = random();
            if (u + v > 1) {
                u = 1 - u;
                v = 1 - v;
            }
            xValues[next] = a[0] + u * (b[0] - a[0]) + v * (c[0] - a[0]);
            yValues[next] = a[1] + u * (b[1] - a[1]) + v * (c[1] - a[1]);
            next++;
        }
    });
    return { xValues, yValues, total };
}

// 3. HOVER TOOLTIP: finds the county under the mouse and shows its name and figures
class CountyTooltipModifier extends CustomChartModifier2D {
    counties;
    highlight;
    tooltip;
    hoveredCounty;

    constructor(counties, highlight) {
        super();
        this.counties = counties;
        this.highlight = highlight;
        this.tooltip = new NativeTextAnnotation({
            text: "",
            isHidden: true,
            textColor: "#FFFFFF",
            fontSize: 15,
            background: "#0F1A2B",
            multiLineAlignment: EMultiLineAlignment.Left,
            padding: new Thickness(6, 10, 6, 10),
            lineSpacing: 4,
            verticalAnchorPoint: EVerticalAnchorPoint.Bottom
        });
    }

    onAttach() {
        super.onAttach();
        this.parentSurface.annotations.add(this.tooltip);
    }

    onDetach() {
        this.parentSurface?.annotations.remove(this.tooltip);
        super.onDetach();
    }

    // The smallest county that contains the point: a few independent cities sit inside a county.
    // This checks every county on each mouse move. The bounding-box test rules most of them out cheaply,
    // which is fast enough for about 3,000 counties. For much more data, such as 85,000 census tracts:
    // - Build a spatial index once: cut the map into a grid of cells (say 50 km) and list, for each cell,
    //   the areas whose bounding box overlaps it. On mouse move, look up the one cell under the mouse
    //   and test only its areas, a handful instead of thousands. A library such as rbush (an R-tree) does the same job.
    // - Skip the search when the mouse is still inside the last area found.
    // - Or use a hit-test bitmap: draw each area offscreen in a unique colour, and read the colour under the mouse.
    findCounty(x, y) {
        let found;
        for (const county of this.counties) {
            const { minX, maxX, minY, maxY } = county.bounds;
            if (x < minX || x > maxX || y < minY || y > maxY) continue;
            if (!county.rings.some((ring) => isPointInRing(x, y, ring))) continue;
            if (!found || county.landArea < found.landArea) found = county;
        }
        return found;
    }

    modifierMouseMove(args) {
        super.modifierMouseMove(args);
        const point = translateFromCanvasToSeriesViewRect(args.mousePoint, this.parentSurface.seriesViewRect);
        const xAxis = this.parentSurface.xAxes.get(0);
        const yAxis = this.parentSurface.yAxes.get(0);
        const x = point ? xAxis.getCurrentCoordinateCalculator().getDataValue(point.x) : NaN;
        const y = point ? yAxis.getCurrentCoordinateCalculator().getDataValue(point.y) : NaN;
        const county = point ? this.findCounty(x, y) : undefined;

        if (county !== this.hoveredCounty) {
            this.hoveredCounty = county;
            this.highlight.clear();
            if (county) {
                const { xValues, yValues } = ringsToLine(county.rings, true);
                this.highlight.appendRange(xValues, yValues);
            }
        }
        if (county) {
            const format = (value, digits) => value.toLocaleString("en-US", { maximumFractionDigits: digits });
            const nearRightEdge = x > xAxis.visibleRange.min + xAxis.visibleRange.diff * 0.6;
            this.tooltip.text = [
                `${county.name}, ${county.state}`,
                `${format(county.density, county.density < 10 ? 1 : 0)} people per sq mile`,
                `Population ${format(county.population, 0)} (${format(county.dotCount, 0)} dots)`,
                `Land area ${format(county.landArea, 1)} sq miles`
            ].join("\n");
            this.tooltip.horizontalAnchorPoint = nearRightEdge ? EHorizontalAnchorPoint.Right : EHorizontalAnchorPoint.Left;
            // Offsets are a fraction of the visible range, so the gap from the cursor looks the same at every zoom level
            this.tooltip.x1 = x + xAxis.visibleRange.diff * (nearRightEdge ? -0.012 : 0.012);
            this.tooltip.y1 = y + yAxis.visibleRange.diff * 0.03;
        }
        this.tooltip.isHidden = !county;
    }

    modifierMouseLeave(args) {
        super.modifierMouseLeave(args);
        this.tooltip.isHidden = true;
        this.hoveredCounty = undefined;
        this.highlight.clear();
    }
}

// 4. THE CHART
// data: counties grouped by state, with outlines in kilometres (Albers equal-area projection),
// such as getUsCountyData() at the end of this file
async function populationDensityMap(divElementId, data) {
    const { wasmContext, sciChartSurface } = await SciChartSurface.create(divElementId, {
        theme: new SciChartJsNavyTheme()
    });

    // A map needs no axis labels, but the hidden axes still set the drawing area, so zoom and pan work as usual.
    // The extra space leaves room for the buttons (top), the legend (right) and the SciChart logo (bottom).
    const xAxis = new NumericAxis(wasmContext, { isVisible: false, growBy: new NumberRange(0.02, 0.22) });
    const yAxis = new NumericAxis(wasmContext, { isVisible: false, growBy: new NumberRange(0.1, 0.12) });
    sciChartSurface.xAxes.add(xAxis);
    sciChartSurface.yAxes.add(yAxis);

    // Unpack the counties: outlines, triangles (for the fill and the dots), bounds and figures
    const counties = [];
    data.counties.forEach(([state, names, populations, landAreas, outlines]) => {
        const nameList = names.split("|");
        outlines.split(",").forEach((encodedRings, i) => {
            const rings = encodedRings.split(" ").map(decodeOutline);
            const triangles = rings.flatMap((ring) => triangulateRing(ring));
            const cumulativeAreas = [];
            let area = 0;
            for (let t = 0; t < triangles.length; t += 3) {
                const [a, b, c] = [triangles[t], triangles[t + 1], triangles[t + 2]];
                area += Math.abs((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])) / 2;
                cumulativeAreas.push(area);
            }
            const xs = rings.flat().map((p) => p[0]);
            const ys = rings.flat().map((p) => p[1]);
            counties.push({
                name: nameList[i],
                state,
                population: populations[i],
                landArea: landAreas[i],
                density: populations[i] / landAreas[i],
                dotCount: 0, // set by setDotValue()
                rings,
                triangles,
                cumulativeAreas,
                bounds: { minX: Math.min(...xs), maxX: Math.max(...xs), minY: Math.min(...ys), maxY: Math.max(...ys) }
            });
        });
    });

    // Choropleth: one triangle series per class, holding the triangles of every county in that class.
    // Denser classes are drawn last, so a city drawn over the county around it stays visible.
    const choroplethSeries = DENSITY_CLASSES.map((densityClass, classIndex) => {
        const triangles = counties
            .filter((county) => getClassIndex(county.density) === classIndex)
            .flatMap((county) => county.triangles);
        return new FastTriangleRenderableSeries(wasmContext, {
            dataSeries: new XyDataSeries(wasmContext, {
                xValues: triangles.map((p) => p[0]),
                yValues: triangles.map((p) => p[1])
            }),
            drawMode: ETriangleSeriesDrawMode.List, // every three points are one triangle
            fill: densityClass.color
        });
    });
    const countyBorders = new FastLineRenderableSeries(wasmContext, {
        dataSeries: new XyDataSeries(wasmContext, {
            ...ringsToLine(
                counties.flatMap((county) => county.rings),
                true
            ),
            isSorted: false,
            containsNaN: true
        }),
        stroke: "#0B142480",
        strokeThickness: 1
    });

    // Dot density: up to 1.6 million dots in one scatter series, refilled when the dot value changes
    const dotData = new XyDataSeries(wasmContext, { isSorted: false, containsNaN: false });
    const dotMarker = new SquarePointMarker(wasmContext, { width: 1, height: 1, strokeThickness: 0 });
    const dotSeries = new XyScatterRenderableSeries(wasmContext, { dataSeries: dotData, pointMarker: dotMarker });

    // State borders and the coast, and the hovered county's outline (filled in by the tooltip modifier)
    const stateBorders = new FastLineRenderableSeries(wasmContext, {
        dataSeries: new XyDataSeries(wasmContext, {
            ...ringsToLine(data.stateBorders.split(" ").map(decodeOutline), false),
            isSorted: false,
            containsNaN: true
        }),
        strokeThickness: 1.5
    });
    const highlight = new XyDataSeries(wasmContext, { isSorted: false, containsNaN: true });
    sciChartSurface.renderableSeries.add(
        ...choroplethSeries,
        countyBorders,
        dotSeries,
        stateBorders,
        new FastLineRenderableSeries(wasmContext, { dataSeries: highlight, stroke: "#FFFFFF", strokeThickness: 2.5 })
    );

    // Legends: annotations in relative coordinates (0 to 1 across the chart), so they stay put when you zoom
    const relative = { xCoordinateMode: ECoordinateMode.Relative, yCoordinateMode: ECoordinateMode.Relative };
    const text = (x1, y1, value, fontSize) =>
        new NativeTextAnnotation({
            ...relative,
            x1,
            y1,
            text: value,
            textColor: "#FFFFFF",
            fontSize,
            multiLineAlignment: EMultiLineAlignment.Left,
            lineSpacing: 3,
            verticalAnchorPoint: EVerticalAnchorPoint.Center
        });
    const choroplethLegend = [
        new BoxAnnotation({ ...relative, x1: 0.81, x2: 0.995, y1: 0.5, y2: 0.97, fill: "#0F1A2BDD", strokeThickness: 0 }),
        text(0.825, 0.565, "People per sq mile\n(2020 Census)", 16)
    ];
    DENSITY_CLASSES.forEach((densityClass, i) => {
        const y = 0.65 + i * 0.062;
        choroplethLegend.push(
            new BoxAnnotation({ ...relative, x1: 0.825, x2: 0.85, y1: y, y2: y + 0.045, fill: densityClass.color, strokeThickness: 0 }),
            text(0.86, y + 0.0225, densityClass.label, 15)
        );
    });
    const dotKey = new BoxAnnotation({ ...relative, x1: 0.825, x2: 0.833, y1: 0.8, y2: 0.814, fill: "#FFD166", strokeThickness: 0 });
    const dotValueText = text(0.845, 0.807, "", 15);
    const dotCountText = text(0.825, 0.895, "", 15);
    const dotLegend = [
        new BoxAnnotation({ ...relative, x1: 0.81, x2: 0.995, y1: 0.74, y2: 0.97, fill: "#0F1A2BDD", strokeThickness: 0 }),
        dotKey,
        dotValueText,
        dotCountText
    ];
    sciChartSurface.annotations.add(...choroplethLegend, ...dotLegend);

    // Change the dot value: recount the dots per county (rounded, so a county of under half a dot gets none),
    // place them again with the same seed, and restyle the dots
    const setDotValue = (peoplePerDot) => {
        const style = DOT_STYLES.find((s) => s.peoplePerDot === peoplePerDot);
        counties.forEach((county) => (county.dotCount = Math.round(county.population / peoplePerDot)));
        const dots = placeDots(counties, createRandom(2020));
        dotData.clear();
        dotData.appendRange(dots.xValues, dots.yValues);
        dotMarker.fill = style.fill;
        dotMarker.width = style.size;
        dotMarker.height = style.size;
        dotValueText.text = `1 dot = ${peoplePerDot.toLocaleString("en-US")} people`;
        dotCountText.text = `${dots.total.toLocaleString("en-US")} dots\n(2020 Census)`;
    };
    setDotValue(DOT_STYLES[0].peoplePerDot);

    // Switch between the two views by showing and hiding series and legends
    const showView = (view) => {
        const isDots = view === "dots";
        choroplethSeries.forEach((series) => (series.isVisible = !isDots));
        countyBorders.isVisible = !isDots;
        dotSeries.isVisible = isDots;
        stateBorders.stroke = isDots ? "#8A9AB5" : "#0B1424";
        choroplethLegend.forEach((annotation) => (annotation.isHidden = isDots));
        dotLegend.forEach((annotation) => (annotation.isHidden = !isDots));
    };
    showView("choropleth");

    // Keep the map's shape: one kilometre on the x axis must take the same space as one on the y axis
    sciChartSurface.preRender.subscribe(() => {
        const rect = sciChartSurface.seriesViewRect;
        if (!rect || !rect.width || !rect.height) return; // not laid out yet
        const { width, height } = rect;
        const xRange = xAxis.visibleRange;
        const yRange = yAxis.visibleRange;
        const kmPerPixel = Math.max(xRange.diff / width, yRange.diff / height);
        const xCentre = (xRange.min + xRange.max) / 2;
        const yCentre = (yRange.min + yRange.max) / 2;
        const newX = new NumberRange(xCentre - (kmPerPixel * width) / 2, xCentre + (kmPerPixel * width) / 2);
        const newY = new NumberRange(yCentre - (kmPerPixel * height) / 2, yCentre + (kmPerPixel * height) / 2);
        if (Math.abs(newX.diff - xRange.diff) > 1e-6) xAxis.visibleRange = newX;
        if (Math.abs(newY.diff - yRange.diff) > 1e-6) yAxis.visibleRange = newY;
    });

    sciChartSurface.chartModifiers.add(
        new CountyTooltipModifier(counties, highlight),
        new MouseWheelZoomModifier(),
        new ZoomPanModifier(),
        new ZoomExtentsModifier()
    );
    return { sciChartSurface, showView, setDotValue };
}
// #region_A_end

// The view and dot value buttons, in the top-left corner of the chart. In your app these can be any buttons.
function addButtonRow(chartRoot, top, label, options, onSelect) {
    const row = document.createElement("div");
    row.style.cssText =
        `position:absolute; top:${top}px; left:14px; display:flex; flex-wrap:wrap; align-items:center; gap:8px;` +
        "z-index:10; font:14px Arial, sans-serif; color:#ffffff;";
    const caption = document.createElement("span");
    caption.textContent = label;
    caption.style.cssText = "min-width:56px;";
    row.append(caption);
    const buttons = options.map((option, i) => {
        const button = document.createElement("button");
        button.textContent = option;
        button.onclick = () => select(i);
        row.append(button);
        return button;
    });
    const highlight = (index) =>
        buttons.forEach((button, i) => {
            button.style.cssText =
                "font:bold 14px Arial, sans-serif; padding:4px 12px; border-radius:14px; cursor:pointer; border:1px solid #50C7E0;" +
                (i === index ? "background:#50C7E0; color:#14233C;" : "background:#14233CCC; color:#ffffff;");
        });
    const select = (index) => {
        onSelect(index);
        highlight(index);
    };
    chartRoot.append(row);
    highlight(0); // the chart starts with the first option
    return row;
}

// 5. THE 3D VIEW: one column per 40 km square, as tall as its population density, standing on the state borders.
// grid: squares of people per sq mile, with state borders in kilometres, such as getUsDensityGrid() at the end of this file
async function populationDensity3D(divElementId, grid) {
    // The map is about 4,640 km east to west and 2,960 km south to north. worldDimensions keeps those proportions,
    // so the map isn't stretched; the height (y) is the population density.
    const { wasmContext, sciChart3DSurface } = await SciChart3DSurface.create(divElementId, {
        theme: new SciChartJsNavyTheme(),
        worldDimensions: new Vector3(464, 160, 296),
        // Look at the middle of the map (x and z run from minus to plus half the world size), just above the floor
        cameraOptions: { position: new Vector3(-200, 300, -420), target: new Vector3(0, 20, 0) }
    });
    const hiddenAxis = { drawLabels: false, drawMajorGridLines: false, drawMinorGridLines: false, drawMajorBands: false };
    const xMin = grid.x0;
    const zMin = grid.y0;
    sciChart3DSurface.xAxis = new NumericAxis3D(wasmContext, {
        ...hiddenAxis,
        visibleRange: new NumberRange(xMin, xMin + grid.columns * grid.cellSize)
    });
    sciChart3DSurface.zAxis = new NumericAxis3D(wasmContext, {
        ...hiddenAxis,
        visibleRange: new NumberRange(zMin, zMin + grid.rows * grid.cellSize)
    });
    sciChart3DSurface.yAxis = new NumericAxis3D(wasmContext, {
        axisTitle: "People per sq mile",
        visibleRange: new NumberRange(0, 18000),
        labelPrecision: 0,
        drawMinorGridLines: false
    });
    sciChart3DSurface.isXYPlaneVisible = false; // hide the back wall; the side wall carries the density scale

    // Columns: x is east, z is north, y (height) is the density. Each square is coloured by its density class.
    const columns = new XyzDataSeries3D(wasmContext);
    grid.runs.forEach(([row, firstColumn, densities]) => {
        densities.forEach((density, i) => {
            const densityClass = DENSITY_CLASSES.find((c) => density < c.max);
            columns.append(
                grid.x0 + (firstColumn + i + 0.5) * grid.cellSize,
                density,
                grid.y0 + (row + 0.5) * grid.cellSize,
                { vertexColor: parseColorToUIntArgb(densityClass.color) }
            );
        });
    });
    sciChart3DSurface.renderableSeries.add(
        new ColumnRenderableSeries3D(wasmContext, {
            dataSeries: columns,
            pointMarker: new CubePointMarker3D(wasmContext),
            dataPointWidthX: grid.cellSize * 0.8, // in kilometres, so there is a small gap between columns
            dataPointWidthZ: grid.cellSize * 0.8,
            useMetadataColors: true
        })
    );

    // State borders on the floor: PointLineRenderableSeries3D with isLineStrip: false draws one line per pair of points
    const borders = new XyzDataSeries3D(wasmContext);
    grid.stateBorders.split(" ").forEach((encoded) => {
        const points = decodeOutline(encoded);
        for (let i = 1; i < points.length; i++) {
            borders.append(points[i - 1][0], 60, points[i - 1][1]); // a little above the floor, so the lines show
            borders.append(points[i][0], 60, points[i][1]);
        }
    });
    sciChart3DSurface.renderableSeries.add(
        new PointLineRenderableSeries3D(wasmContext, { dataSeries: borders, isLineStrip: false, stroke: "#C8D3E8", strokeThickness: 1.5 })
    );

    // Drag to rotate, scroll to zoom, double-click to reset, and hover a column to read its density
    const allDensities = grid.runs.flatMap(([, , densities]) => densities).sort((a, b) => b - a);
    sciChart3DSurface.chartModifiers.add(
        new OrbitModifier3D(),
        new MouseWheelZoomModifier3D(),
        new ResetCamera3DModifier(),
        new TooltipModifier3D({
            tooltipContainerBackground: "#0F1A2B",
            tooltipTextStroke: "#FFFFFF",
            tooltipDataTemplate: (seriesInfo) => {
                if (!seriesInfo || !seriesInfo.isHit || seriesInfo.renderableSeries !== sciChart3DSurface.renderableSeries.get(0)) return [];
                const density = seriesInfo.yValue;
                return [
                    `${density.toLocaleString("en-US")} people per sq mile`,
                    `Rank ${(allDensities.indexOf(density) + 1).toLocaleString("en-US")} of ${allDensities.length.toLocaleString("en-US")} squares (1 = densest)`
                ];
            }
        })
    );
    return { sciChart3DSurface };
}

// A colour key in the top-right corner. In your app this can be any HTML.
function add3DLegend(chartRoot) {
    const legend = document.createElement("div");
    legend.style.cssText =
        "position:absolute; top:10px; right:12px; z-index:10; padding:8px 12px; border-radius:6px;" +
        "background:#0F1A2BDD; color:#ffffff; font:14px Arial, sans-serif; line-height:22px;";
    legend.innerHTML =
        "People per sq mile<br>" +
        DENSITY_CLASSES.map(
            (c) => `<span style="display:inline-block; width:14px; height:14px; margin-right:8px; vertical-align:-2px; background:${c.color}"></span>${c.label}`
        ).join("<br>");
    chartRoot.append(legend);
}

// The 2D map and the 3D view share one page: each gets its own div inside scichart-root, and the
// View buttons show one and hide the other. The 3D chart is only created the first time 3D is chosen.
const chartRoot = document.getElementById("scichart-root");
chartRoot.style.position = "relative";
const addLayer = (id) => {
    const layer = document.createElement("div");
    layer.id = id;
    layer.style.cssText = "position:absolute; inset:0;";
    chartRoot.append(layer);
    return layer;
};
const layer2d = addLayer("population-map-2d");
const layer3d = addLayer("population-map-3d");
layer3d.style.visibility = "hidden";

populationDensityMap("population-map-2d", getUsCountyData()).then(({ showView, setDotValue }) => {
    let surface3d; // created on first use
    const dotRow = addButtonRow(chartRoot, 44, "1 dot =", ["200", "1,000", "5,000 people"], (i) =>
        setDotValue(DOT_STYLES[i].peoplePerDot)
    );
    dotRow.style.visibility = "hidden"; // shown with the dot density view
    addButtonRow(chartRoot, 10, "View", ["Choropleth", "Dot density", "3D"], (i) => {
        const is3d = i === 2;
        if (!is3d) showView(i === 0 ? "choropleth" : "dots");
        dotRow.style.visibility = i === 1 ? "visible" : "hidden";
        layer2d.style.visibility = is3d ? "hidden" : "visible";
        layer3d.style.visibility = is3d ? "visible" : "hidden";
        if (is3d && !surface3d) {
            surface3d = populationDensity3D("population-map-3d", getUsDensityGrid()).then(({ sciChart3DSurface }) =>
                add3DLegend(sciChart3DSurface.domChartRoot)
            );
        }
    });
});

